export function bindVersionHistory({flush,receive,openDialog,esc,toast}){
 const request=async(action,data)=>{const response=await fetch('/api/versions'+action,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error);return value;};
 const guard=fn=>async()=>{try{await fn();}catch(error){toast(error.message);const node=document.querySelector('#version-message');if(node)node.textContent=error.message;}};
 const open=guard(async()=>{await flush();const {versions}=await request('');openDialog('历史版本',`<p>本机保留最近 100 个工作台版本，从本功能启用后开始记录。还原会生成新版本，并同步给工作区成员；原图仍使用现有素材。</p><p id="version-message" class="error"></p>${versions.map(v=>`<section class="list-card"><div><strong>版本 ${v.revision}</strong> · ${esc(new Date(v.at).toLocaleString('zh-CN'))}<p>${esc(v.reason)}</p><button data-version="${esc(v.id)}">查看差异</button></div></section>`).join('')||'<p>尚无历史版本。</p>'}`);
  for(const button of document.querySelectorAll('[data-version]'))button.onclick=guard(async()=>{const preview=await request('/preview',{id:button.dataset.version});openDialog('还原版本预览',`<p>将还原至版本 ${preview.revision}，涉及 ${preview.changes.length} 条业务记录。确认前请检查以下差异。</p><p id="version-message" class="error"></p>${preview.changes.map(c=>`<details><summary>${esc(c.type)} · ${esc(c.name)}</summary><pre>${esc(JSON.stringify({当前:c.before,还原后:c.after},null,2))}</pre></details>`).join('')}<div class="actions"><button id="version-back">返回历史</button><button id="version-apply" class="primary" ${preview.changes.length?'':'disabled'}>备份当前并还原</button></div>`);document.querySelector('#version-back').onclick=open;document.querySelector('#version-apply').onclick=guard(async()=>{document.querySelector('#version-apply').disabled=true;try{await request('/restore',{id:preview.id,hash:preview.hash,baseRevision:preview.baseRevision});document.querySelector('#dialog').close();await receive();toast('已还原并保存为新版本');await open();}catch(e){document.querySelector('#version-apply').disabled=false;throw e;}});});
 });return {open};
}
